const canvas = document.createElement('canvas');
canvas.width = 1080;
canvas.height = 1440;
const ctx = canvas.getContext('2d');

// 背景渐变：深蓝紫到科技蓝
const grad = ctx.createLinearGradient(0, 0, 1080, 1440);
grad.addColorStop(0, '#0f0c29');
grad.addColorStop(0.5, '#302b63');
grad.addColorStop(1, '#24243e');
ctx.fillStyle = grad;
ctx.fillRect(0, 0, 1080, 1440);

// 装饰：右上角光晕
const glow = ctx.createRadialGradient(900, 200, 0, 900, 200, 400);
glow.addColorStop(0, 'rgba(0,212,255,0.25)');
glow.addColorStop(1, 'rgba(0,212,255,0)');
ctx.fillStyle = glow;
ctx.fillRect(0, 0, 1080, 1440);

// 左下光晕
const glow2 = ctx.createRadialGradient(150, 1200, 0, 150, 1200, 350);
glow2.addColorStop(0, 'rgba(139,92,246,0.2)');
glow2.addColorStop(1, 'rgba(139,92,246,0)');
ctx.fillStyle = glow2;
ctx.fillRect(0, 0, 1080, 1440);

// 顶部标签
ctx.fillStyle = 'rgba(0,212,255,0.15)';
ctx.beginPath();
ctx.roundRect(60, 100, 280, 56, 28);
ctx.fill();
ctx.fillStyle = '#00d4ff';
ctx.font = 'bold 28px "PingFang SC", "Microsoft YaHei", sans-serif';
ctx.textAlign = 'center';
ctx.fillText('🤖 开源效率神器', 200, 137);

// 主标题第一行
ctx.textAlign = 'left';
ctx.fillStyle = '#ffffff';
ctx.font = 'bold 88px "PingFang SC", "Microsoft YaHei", sans-serif';
ctx.fillText('浏览器里', 80, 310);

// 主标题第二行（高亮）
ctx.fillStyle = '#00d4ff';
ctx.fillText('住了个AI', 80, 420);
ctx.fillStyle = '#ffffff';
ctx.fillText('打工人', 80, 530);

// 副标题
ctx.fillStyle = 'rgba(255,255,255,0.7)';
ctx.font = '36px "PingFang SC", "Microsoft YaHei", sans-serif';
ctx.fillText('Browser Copilot · 工作流自动化', 80, 620);

// 分隔线
const lineGrad = ctx.createLinearGradient(80, 680, 600, 680);
lineGrad.addColorStop(0, '#00d4ff');
lineGrad.addColorStop(1, 'rgba(0,212,255,0)');
ctx.fillStyle = lineGrad;
ctx.fillRect(80, 680, 520, 3);

// 卖点胶囊
const capsules = [
  { icon: '💬', text: '对话生成工作流' },
  { icon: '⚡', text: '零代码浏览器自动化' },
  { icon: '🧠', text: 'AI Agent 驱动' },
  { icon: '🔥', text: '比 Automa 更强' }
];

let cy = 740;
capsules.forEach((c, i) => {
  // 胶囊背景
  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  ctx.beginPath();
  ctx.roundRect(80, cy, 500, 72, 36);
  ctx.fill();

  // 左侧亮色边
  ctx.fillStyle = '#00d4ff';
  ctx.beginPath();
  ctx.roundRect(80, cy, 6, 72, 3);
  ctx.fill();

  // 文字
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 34px "PingFang SC", "Microsoft YaHei", sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText(`${c.icon}  ${c.text}`, 110, cy + 48);
  cy += 92;
});

// 流程图示意区域
const flowY = 1130;
ctx.fillStyle = 'rgba(255,255,255,0.05)';
ctx.beginPath();
ctx.roundRect(60, flowY - 20, 960, 160, 20);
ctx.fill();

ctx.fillStyle = 'rgba(255,255,255,0.5)';
ctx.font = '26px "PingFang SC", "Microsoft YaHei", sans-serif';
ctx.textAlign = 'center';
ctx.fillText('— 工作流示意 —', 540, flowY + 10);

// 流程节点
const nodes = ['你说需求', 'AI 理解', '自动操作', '导出结果'];
const nodeColors = ['#6366f1', '#8b5cf6', '#06b6d4', '#10b981'];
const startX = 140;
const spacing = 220;
nodes.forEach((n, i) => {
  const nx = startX + i * spacing;
  ctx.fillStyle = nodeColors[i];
  ctx.beginPath();
  ctx.roundRect(nx - 70, flowY + 30, 140, 56, 14);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.font = 'bold 26px "PingFang SC", "Microsoft YaHei", sans-serif';
  ctx.fillText(n, nx, flowY + 66);

  // 箭头
  if (i < 3) {
    ctx.fillStyle = 'rgba(255,255,255,0.4)';
    ctx.font = '30px sans-serif';
    ctx.fillText('→', nx + 90, flowY + 66);
  }
});

// 底部出处
ctx.fillStyle = 'rgba(255,255,255,0.4)';
ctx.font = '26px "PingFang SC", "Microsoft YaHei", sans-serif';
ctx.textAlign = 'center';
ctx.fillText('GitHub 开源 · dcc123456/browser-copilot', 540, 1390);

automaSetVariable('coverImage', canvas.toDataURL('image/png'));
automaNextBlock('cover generated');

const text = `{{aiPostContent}}`

const el = document.querySelector('#post-textarea') || document.querySelector('[contenteditable="true"]');
el.focus();
const range = document.createRange();
range.selectNodeContents(el); range.collapse(false);
const sel = getSelection(); sel.removeAllRanges(); sel.addRange(range);
document.execCommand('insertText', false, text);
if (el.textContent.trim().length < 20) {
  el.dispatchEvent(new InputEvent('beforeinput', {inputType:'insertText', data:text, bubbles:true, cancelable:true}));
}
if (el.textContent.trim().length < 20) {
  el.innerHTML = text.split('\n').map(l=>l?`<p>${l}</p>`:'<p><br></p>').join('');
  el.dispatchEvent(new InputEvent('input',{bubbles:true}));
}
return {len: el.textContent.length};

